sealed class Shape {}
class Circle extends Shape { final double radius; Circle(this.radius); }
double area(Shape shape) => switch (shape) { Circle(radius: final r) when r > 0 => 3.14 * r * r, _ => 0 };
void main() { final (name, count) = ('world', 2); print('Hello $name: ${count + 1}'); final pattern = RegExp(r'\d+'); }
